def bounding_box_from_data(data):
    """return the coordinates (in RAI) of the corners of a box enclosing the data in ``data``"""
    return (data.x.min(), data.y.min(), data.x.max(), data.y.max())


def bounding_box_from_data_list(data_list):
    """return the coordinates (in RAI) of the corners of a box enclosing the data in ``data_list``"""
    return (
        min(d.x.min() for d in data_list),
        min(d.y.min() for d in data_list),
        max(d.x.max() for d in data_list),
        max(d.y.max() for d in data_list),
    )


